                                      '    plain = _first(FG.run_scenario("sandbox_basic", lib=lib, probe=False, '
                                      'checkpoints=["sandbox_00"]))\n'
                                      '    sp = _first(FG.run_scenario_split("sandbox_basic", lib=lib, probe=False, '
                                      'checkpoints=["sandbox_00"]))\n'
                                      '    for k in FG.COLUMNS:\n'
                                      '        if k not in ("seconds",):\n'
                                      '            assert sp.get(k) == plain.get(k), k\n'
                                      '    assert plain["status"] == "FAIL"                     # I14\'s 125 one-level px under '
                                      'GlRaster\n'
                                      '    assert sp["split_status"] == "PASS" and sp["twod_px"] == 0 and '
                                      'sp["terrain_origin_px"] > 0\n'
                                      '\n'
                                      '\n'
                                      'def test_run_control_2d_plant_in_hud_stays_fail(lib, monkeypatch):\n'
                                      '    monkeypatch.setenv("SG_FRAMEGATE_PLANT", "both:hud_title:6")\n'
                                      '    sp = _first(FG.run_scenario_split("sandbox_basic", lib=lib, probe=False, '
                                      'checkpoints=["sandbox_00"]))\n'
                                      '    assert sp["split_status"] == "FAIL" and sp["twod_px"] >= 6 and "hud_title" in '
                                      'sp["split_detail"]\n'
                                      '\n'
                                      '\n'
                                      'def test_run_control_terrain_only_plant_reads_fail_as_terrain_origin(lib, monkeypatch):\n'
                                      '    monkeypatch.setenv("SG_FRAMEGATE_PLANT", f"raster:view:{GR.MAX_BIG + 40}")\n'
