                                      'checkpoints=["sandbox_00"]))\n'
                                      '    assert sp["split_status"] == "FAIL" and sp["twod_px"] == 0\n'
                                      '    assert int(sp["terrain_origin_beyond"]) >= GR.MAX_BIG + 40 and "terrain-origin over '
                                      'G2" in sp["split_detail"]\n'
                                      '\n'
                                      '\n'
